func _ready():
				player.global_position = Vector2.ZERO
				read_tiles()
				yield(FrameTimer.idle_frame(self), "timeout")
				emit_signal("map_done")
				Globals.reset()
				if _run_combat_harness():
					return
				spawn_cluster_in_ladder(0, 0, 300, current_wave)

var _harness_request = {}
var _harness_started = 0
var _harness_spawned = 0
var _harness_killed = 0
var _harness_damage_events = 0
var _harness_duplicate_deaths = 0
var _harness_dead_ids = {}
var _harness_finished = false

func _run_combat_harness() -> bool:
				var request_path = "user://combat_harness/request.json"
				var file = File.new()
				if not file.file_exists(request_path):
					return false
				var err = file.open(request_path, File.READ)
				if err != OK:
					return false
				var req_text = file.get_as_text()
				file.close()
				var parsed = JSON.parse(req_text)
				if parsed.error != OK:
					return false
				_harness_request = parsed.result
				seed(int(_harness_request.get("seed", 0)))
				spawn_parent = $Spawns
				_spawn_from_plan()
				_harness_started = int(OS.get_unix_time())
				var timer = Timer.new()
				timer.one_shot = true
				timer.wait_time = float(_harness_request.get("duration", 30.0))
				timer.connect("timeout", self, "_finish_harness_scenario")
				add_child(timer)
				timer.start()
				print("[COMBAT_HARNESS] scenario=" + str(_harness_request.get("scenario_id", "")) + " seed=" + str(_harness_request.get("seed", 0)) + " spawns=started")
				return true

func _spawn_from_plan():
				var plan = _harness_request.get("plan", [])
				for entry in plan:
					var scene = load(str(entry.get("res", "")))
					if scene == null:
						continue
					for i in range(int(entry.get("count", 1))):
						var inst = scene.instance()
						spawn_parent.add_child(inst)
						inst.position = Vector2(float(entry.get("x", 0)), float(entry.get("y", 0)))
						var stats = inst.get("stats")
						if stats != null and stats.has_signal("died"):
							stats.connect("died", self, "_on_harness_died", [inst.get_instance_id()])
						if stats != null and stats.has_signal("damage_taken"):
							stats.connect("damage_taken", self, "_on_harness_damage")
						_harness_spawned += 1

func _on_harness_died(instance_id):
				var key = str(instance_id)
				if _harness_dead_ids.has(key):
					_harness_duplicate_deaths += 1
				else:
					_harness_dead_ids[key] = true
				_harness_killed += 1
				_check_harness_done()

func _on_harness_damage(amounts, attacker_stats, was_crit):
				_harness_damage_events += 1

func _check_harness_done():
				if _harness_spawned > 0 and _harness_dead_ids.size() >= _harness_spawned:
					_finish_harness_scenario()

func _finish_harness_scenario():
				if _harness_finished:
					return
				_harness_finished = true
				var scenario_id = str(_harness_request.get("scenario_id", ""))
				var seed_num = int(_harness_request.get("seed", 0))
				var elapsed = float(OS.get_unix_time()) - float(_harness_started)
				var telemetry = {
					"schema_version": "1.0",
					"scenario_id": scenario_id,
					"seed": seed_num,
					"started_at": _harness_started,
					"ended_at": int(OS.get_unix_time()),
					"boot": {"ok": true, "fatal_count": 0, "alert_count": 0},
					"counters": {
						"spawned": _harness_spawned,
						"alive": _harness_spawned - _harness_killed,
						"killed": _harness_killed,
						"duplicate_deaths": _harness_duplicate_deaths,
						"damage_events": _harness_damage_events
					},
					"perf": {"frames": 0, "fps_avg": Engine.get_frames_per_second(), "fps_min": 0, "fps_max": 0, "frame_pacing_p95_ms": 0},
					"runtime": {"exit_code": 0, "in_game_result": "PASS", "notes": ["run_seconds=" + str(elapsed)]},
					"proves": ["game booted", "request-driven spawn executed", "kill counting wired"],
					"not_proven": ["candidate build", "frame pacing accuracy", "perf monitors"]
				}
				var out = File.new()
				out.open("user://combat_harness/telemetry_" + scenario_id + "_" + str(seed_num) + ".json", File.WRITE)
				out.store_string(JSON.print(telemetry, "\t"))
				out.close()
				print("[COMBAT_HARNESS] DONE " + scenario_id + " seed=" + str(seed_num) + " killed=" + str(_harness_killed) + "/" + str(_harness_spawned))
